const copy={
en:{portal:'Course Portal',ch1:'Chapter 1 · Data',ch2:'Chapter 2 · Visualization Process',ch3:'Chapter 3 · Color',ch4:'Chapter 4 · Low-dimensional Visualization',ch5:'Chapter 5 · Temporal Visualization',heroTitle:'Chapter 1 · Data',heroSub:'Doc-01 integrated lesson · Explanation ⇄ Code ⇄ Demo tabs',tip:'Switch sections · freely switch among three tabs',toc:'Contents',n11:'Data Generation',n12:'Data Definition',n13:'Data Attributes',n14:'Data Transformation',n15:'D3 Data Selection',n16:'Page Layout',demoSet:'Supplementary demos',markdown:'Complete lecture markdown',explain:'Explanation',code:'Key Code',demo:'Demo',s11sub:'Asynchronous loading and field mapping with synthetic student data',caseTitle:'The original case',caseBody:'This chapter uses synthetic records representing the 2025 freshman cohort of China University of Petroleum (East China). To protect privacy, the dataset was generated with DeepSeek. The file data/newstudent.csv contains 80 records.',theoryTitle:'Embedded theory: reliability limits of AI-generated data',quality:'Four dimensions of data quality',dimensions:'accuracy / completeness / consistency / timeliness.',complete:'Completeness: all required fields are present',accuracy:'Accuracy: names and origins are fictional and cannot support real demographic analysis',bias:'Sampling bias: the model favors distributions that “look reasonable”',keyPoint:'Class takeaway:',keyBody:'Synthetic data is suitable for teaching, but it must be labeled to avoid being mistaken for a real distribution.',p12:'Distinguish data, information, knowledge, and wisdom to build the conceptual foundation for visualization.',p13:'Identify nominal, ordinal, interval, and ratio attributes, and understand how types constrain visual encoding.',p14:'Use filtering, aggregation, and derivation to turn raw records into structures that answer questions.',p15:'Understand the mapping between data joins and DOM elements as the update model for dynamic visualization.',s16sub:'From information structure to responsive interfaces: rebuilding a campus events site with a layout system',takeaway:'Core takeaway',takeawayBody:'Layout expresses information relationships; it is not a pile of element positions.',problemTitle:'Case problem: Why does CampusHub feel disorganized?',problemBody:'Fixed widths, arbitrary margins, and absolute positioning work only in one screenshot. When content grows or the screen narrows, navigation crowds, cards lose alignment, and the sidebar disrupts reading order.',methodTitle:'Think in relationships, not properties',symptom:'Symptom',issue:'Problem',principle:'Principle',decision:'Decision',result:'Result',k1:'Start with meaningful document and reading order so growing content naturally pushes what follows.',k2:'When relationships mainly occur along one direction, use a one-dimensional model for distribution and alignment.',k3:'When content must share rows and columns, use a two-dimensional coordinate system.',k4:'Keep within-group space smaller than between-group space to express proximity and rhythm.',k5:'Use fluid and intrinsic layout first; add breakpoints only where a content relationship fails.',k6:'Keep visual, reading, and keyboard focus order consistent.',judge:'Layout decision:',judgeBody:'Use Normal Flow for natural reading, Flexbox for one direction, Grid for two directions, and Position only for detached relationships.',copy:'Copy code',c1:'Combines a comfortable maximum with fluid width.',c2:'Defines spacing as a container rule instead of scattered margins.',c3:'Lets the main track truly shrink so long content does not break the layout.',c4:'The breakpoint comes from the point where the content relationship fails.',run:'Run in demo',labTitle:'Layout Lab · Five layout experiments',labSub:'Change a constraint, observe the result, then explain it with a layout principle.',decisionLab:'Decision Tree',flexTitle:'Flexbox: distribute and align on one axis',flexIntro:'Navigation is a one-dimensional relationship. When direction changes, the main axis changes with it; wrapping simply continues the one-dimensional calculation across independent flex lines.',containerWidth:'Container width',navDiscover:'Discover events',navClubs:'Browse clubs',navProfile:'Profile',why:'Why?',gridTitle:'Grid Playground: share row-and-column coordinates',gridIntro:'Adjust track count, card minimum, and gap. With auto-fit enabled, container space and the content minimum decide the number of columns.',columns:'Fixed columns',minCard:'Minimum card width',event4:'Film Screening',event5:'Morning Run',event6:'Maker Workshop',activeRule:'Active rule',treeTitle:'Layout decision tree: identify the relationship first',treeIntro:'Answer no more than two questions. The recommendation explains the reason instead of merely saying right or wrong.',treeQ1:'Must the content align across both rows and columns?',treeQ2:'Do multiple elements mainly cooperate along one direction?',yes:'Yes',no:'No',recommendation:'Recommendation',treeWaiting:'Begin with the first question.',restart:'Start again',compareTitle:'Before / After: same content, two spatial systems',compareIntro:'Drag the divider to compare fixed sizing and arbitrary spacing with a fluid container and consistent rhythm.',campusEvents:'Campus Events',fixedIssues:'Fixed width · arbitrary spacing · weak hierarchy',fluidWins:'Fluid container · spacing system · clear hierarchy',beforeNote:'Works for only one screenshot',afterNote:'Adapts to content and space',cqTitle:'Container Query: respond to the component’s own space',cqIntro:'This is the same Event Card with unchanged HTML. It expands horizontally in the wide main area and stacks vertically in the narrow sidebar.',putMain:'Place in main area',putSide:'Place in sidebar',mainArea:'MAIN · Main area',sideArea:'SIDEBAR',eventDesc:'Meet new people and create a campus poster together in one evening.',componentState:'Component state',campusNav:'Discover　Clubs　Events',signin:'Sign in',week:'THIS WEEK',campusTitle:'Make campus feel smaller.',event1:'Design Night',event2:'Open Stage',event3:'Green Market',popular:'Popular now',heuristic:'uses teaching guidance, not a formal Web standard.'}}
let lang=localStorage.getItem('course-lang')||'zh';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function setLang(next){lang=next;localStorage.setItem('course-lang',lang);document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=lang==='zh'?'第 1 章 · 数据｜课程门户':'Chapter 1 · Data | Course Portal';$$('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));$$('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(lang==='en'&&copy.en[k])el.textContent=copy.en[k];else if(el.dataset.zh)el.textContent=el.dataset.zh});refreshDynamic();}
$$('[data-i18n]').forEach(el=>el.dataset.zh=el.textContent);$$('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));
function showTab(name){$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));['explain','code','demo'].forEach(x=>$(`#${x}Panel`).classList.toggle('hidden',x!==name));}
$$('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));$('#runDemo').onclick=()=>showTab('demo');
$('#copyCode').onclick=async()=>{const text=$('.codebox code').textContent;await navigator.clipboard.writeText(text);$('#copyCode').textContent=lang==='zh'?'已复制':'Copied'};
let currentLab='flex',treeChoice=null,cqTarget='main';
$$('[data-lab]').forEach((button,index)=>button.onclick=()=>{currentLab=button.dataset.lab;$$('[data-lab]').forEach(x=>x.classList.toggle('active',x===button));$$('[data-lab-panel]').forEach(panel=>panel.classList.toggle('hidden',panel.dataset.labPanel!==currentLab));$('#labNumber').textContent=String(index+1).padStart(2,'0')});

const flexDirection=$('#flexDirection'),flexJustify=$('#flexJustify'),flexAlign=$('#flexAlign'),flexWrap=$('#flexWrap'),flexWidth=$('#flexWidth');
function updateFlex(){const box=$('#flexPlayground'),direction=flexDirection.value;box.style.flexDirection=direction;box.style.justifyContent=flexJustify.value;box.style.alignItems=flexAlign.value;box.style.flexWrap=flexWrap.value;box.style.width=flexWidth.value+'px';$('#flexWidthValue').textContent=flexWidth.value+' px';$('.axes-stage').classList.toggle('column-mode',direction==='column');$('#mainAxis').textContent=direction==='column'?'MAIN AXIS ↓':'MAIN AXIS →';$('#crossAxis').textContent=direction==='column'?'CROSS AXIS →':'CROSS AXIS ↓';$('#flexCode').textContent=`flex-direction: ${direction}; justify-content: ${flexJustify.value}; align-items: ${flexAlign.value}; flex-wrap: ${flexWrap.value};`;$('#flexInsight').textContent=lang==='zh'?(direction==='column'?'主轴现在是纵向；justify-content 控制上下分配。':'主轴现在是横向；justify-content 控制左右分配。'):(direction==='column'?'The main axis is vertical; justify-content controls vertical distribution.':'The main axis is horizontal; justify-content controls horizontal distribution.')}
[flexDirection,flexJustify,flexAlign,flexWrap,flexWidth].forEach(el=>el.oninput=updateFlex);

const gridColumns=$('#gridColumns'),gridMin=$('#gridMin'),gridGap=$('#gridGap'),gridAuto=$('#gridAuto');
function updateGrid(){const area=$('#gridPlayground'),cols=gridColumns.value,min=gridMin.value,gap=gridGap.value,auto=gridAuto.checked;$('#gridColumnsValue').textContent=cols;$('#gridMinValue').textContent=min+' px';$('#gridGapValue').textContent=gap+' px';area.style.gap=gap+'px';area.style.gridTemplateColumns=auto?`repeat(auto-fit, minmax(min(100%, ${min}px), 1fr))`:`repeat(${cols}, minmax(0, 1fr))`;$('#gridCode').textContent=`grid-template-columns: ${area.style.gridTemplateColumns}; gap: ${gap}px;`;$('#gridInsight').textContent=lang==='zh'?(auto?'列数现在由容器宽度和卡片最小宽度共同决定。':'固定列数会保持明确轨道，即使每张卡片变窄。'):(auto?'Container width and the card minimum now decide the column count together.':'A fixed column count preserves explicit tracks even as cards narrow.')}
[gridColumns,gridMin,gridGap,gridAuto].forEach(el=>el.oninput=updateGrid);

const treeText={grid:{name:'CSS Grid',zh:'需要同时对齐行与列，这是二维关系。',en:'Rows and columns must align together, so this is a two-dimensional relationship.'},flex:{name:'Flexbox',zh:'元素主要沿一条轴协作，使用一维布局模型。',en:'The elements cooperate mainly along one axis, so use a one-dimensional model.'},flow:{name:'Normal Flow',zh:'不需要额外坐标关系，让文档自然顺序完成布局。',en:'No extra coordinate relationship is needed; let document order perform the layout.'}};
function showTreeResult(key){treeChoice=key;const result=$('#treeResult'),data=treeText[key];result.querySelector('strong').textContent=data.name;result.querySelector('p').textContent=data[lang]}
$$('[data-tree]').forEach(button=>button.onclick=()=>{const action=button.dataset.tree;if(action==='next'){$('#treeStep2').classList.remove('hidden');treeChoice=null;$('#treeResult strong').textContent='—';$('#treeResult p').textContent=lang==='zh'?'继续回答第二个问题。':'Continue with the second question.'}else showTreeResult(action)});
$('#treeReset').onclick=()=>{treeChoice=null;$('#treeStep2').classList.add('hidden');$('#treeResult strong').textContent='—';$('#treeResult p').textContent=lang==='zh'?'从第一个问题开始。':'Begin with the first question.'};

$('#compareRange').oninput=e=>$('#compareWrap').style.setProperty('--split',e.target.value+'%');
function updateCq(){const card=$('#cqCard'),target=cqTarget==='main'?$('#cqMain'):$('#cqSide');target.appendChild(card);$$('[data-cq-target]').forEach(button=>button.classList.toggle('active',button.dataset.cqTarget===cqTarget));$('#cqState').textContent=lang==='zh'?(cqTarget==='main'?'宽容器 ≥ 32rem：横向卡片':'窄容器 < 32rem：纵向卡片'):(cqTarget==='main'?'Wide container ≥ 32rem: horizontal card':'Narrow container < 32rem: vertical card')}
$$('[data-cq-target]').forEach(button=>button.onclick=()=>{cqTarget=button.dataset.cqTarget;updateCq()});
function refreshDynamic(){if($('#flexPlayground'))updateFlex();if($('#gridPlayground'))updateGrid();if(treeChoice)showTreeResult(treeChoice);if($('#cqCard'))updateCq()}
const tocLinks=$$('#tocNav a');tocLinks.forEach(a=>a.onclick=()=>{tocLinks.forEach(x=>x.classList.remove('active'));a.classList.add('active')});
const observer=new IntersectionObserver(entries=>{const hit=entries.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!hit)return;tocLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+hit.target.id))},{rootMargin:'-20% 0px -60% 0px',threshold:[0,.2,.5]});$$('.lesson').forEach(s=>observer.observe(s));setLang(lang);
